// orient each instanced cone along its velocity
const dir=_vDiff.copy(vel).divideScalar(speedLen||1);
_quaternion.setFromUnitVectors(_forwardZ, dir);
_matrix.compose(pos,_quaternion,_scaleVec);
instancedMesh.setMatrixAt(i,_matrix);

